        /// <summary>
        /// Gets all the distinct Pallets for the Branch and Shipment, joining with the F4215 to ensure
        /// they are at a valid Shipment Status
        /// </summary>
        /// <param name="branchPlant">Branch Plant (CDMCU)</param>
        /// <param name="shipmentNumber">Shipment Number (CDSHPN)</param>
        /// <param name="palletNumber">Pallet Number (CDURRF)</param>
