        #region GetDistinctCartonPalletsAtStatus

        /// <summary>
        /// Gets all the distinct Cartons or Pallets for the Branch and Shipment, joining with the F4215 to ensure
        /// they are at a valid Shipment Status
        /// </summary>
        /// <param name="branchPlant">Branch Plant (CDMCU)</param>
        /// <param name="shipmentNumber">Shipment Number (CDSHPN)</param>
        /// <param name="cartonPalletNumber">Carton/Pallet Serial Number (CDURRF)</param>
        /// <param name="recordType">Record Type to filter by (Pallet, Carton, or Item)</param>
        /// <param name="allowedShipmentStatues">Collection of Allowed Shipment Statuses (XHSSTS)</param>
        /// <returns>True if the Fetch was successful at retrieving any records, otherwise, False</returns>
        private bool GetDistinctCartonPalletsAtStatus(string branchPlant, double shipmentNumber, string cartonPalletNumber, RecordType recordType, IEnumerable<string> allowedShipmentStatues)
        {
            ResetAll();

            SQL = String.Format("SELECT DISTINCT CDURRF FROM {0} ", GetFullTableName());
            SQL = String.Format("INNER JOIN {0} ON (XHSHPN = CDSHPN) ", GetFullTableName("F4215"));

            SQL = String.Format("WHERE (CDMCU = '{0}') AND (CDSHPN = {1}) ", Columns.CDMCU.UnformatColumn(branchPlant), shipmentNumber);

            if (recordType == RecordType.Pallet)
            {
                SQL = "AND (CDITM = 0) ";
            }
            else if ((recordType == RecordType.Carton) || (recordType == RecordType.Item))
            {
                SQL = "AND (CDITM <> 0) ";
            }

            if (cartonPalletNumber != null)
            {
                SQL = String.Format("AND (CDURRF = '{0}') ", cartonPalletNumber);
            }

            if ((allowedShipmentStatues != null) && (allowedShipmentStatues.Count() > 0) && (!String.IsNullOrWhiteSpace(allowedShipmentStatues.First())) && (allowedShipmentStatues.First().Trim() != "*"))
            {
                SQL = String.Format("AND (XHSSTS IN ('{0}')) ", String.Join("','", allowedShipmentStatues));
            }

            return Fetch();
        }

