        /// <summary>
        /// Retrieves all the distinct items on a Pallet
        /// </summary>
        /// <param name="palletUniqueID">Unique ID (CDUKID)</param>
        /// <returns>True if the Fetch was successful at retrieving any records, otherwise, False</returns>
        public bool FetchDistinctPalletItems(double palletUniqueID)
        {
            ResetAll();

            SQL = String.Format("SELECT CDITM, COUNT(*) AS TotalCartons, COALESCE(SUM(CDTQTY), 0) AS TotalPieces, MAX(CDUKID) AS CDUKID FROM {0} ", GetFullTableName());
            SQL = String.Format("WHERE (CDCROS IN (SELECT CDCRID FROM {0} WHERE (CDUKID = {1}))) ", GetFullTableName(), palletUniqueID);
            SQL = "GROUP BY CDITM ORDER BY CDITM";

            return Fetch();
        }

