            SQL = String.Format("WHERE (CDCROS IN (SELECT CDCRID FROM {0} WHERE (CDUKID = {1}))) AND CDITM = {2} ", GetFullTableName(), palletUniqueID, shortItemNumber);
            SQL = "GROUP BY CDITM ORDER BY CDITM";

