        #region RetrieveCartonItemQty

        /// <summary>
        /// Retrieves the Item on a Pallet (using the Outside Carton ID), and pulling back summed quantities for the
        /// carton quantities, total count, expected total quantity, ext
        /// </summary>
        /// <param name="branchPlant">Branch Plant (CDMCU)</param>
        /// <param name="shortItemNumber">Short Item Number (CDITM)</param>
        /// <param name="outsideCartonID">Outside Carton ID (CDCROS), the CDCRID of the Pallet</param>
        /// <returns>True if the Fetch was successful at retrieving any records, otherwise, False</returns>
        public bool RetrieveCartonItemQty(string branchPlant, double shortItemNumber, double outsideCartonID)
        {
            ResetAll();

            SQL = "SELECT CDITM, COUNT(*) AS TotalCount, SUM(CDTQTY) AS CDTQTY, SUM(CDUPQT) AS CDUPQT, SUM(CDGWEI) AS CDGWEI, COALESCE(SUM(SDSOQS), 0) AS TotalBoxQuantity ";
            SQL = String.Format("FROM {0} ", GetFullTableName());
            SQL = String.Format("LEFT JOIN (SELECT SDSHPN, SDITM, SUM(SDSOQS) AS SDSOQS FROM {0} GROUP BY SDSHPN, SDITM) AS X ON (X.SDSHPN = CDSHPN) AND (X.SDITM = CDITM) ", GetFullTableName("F4211"));

            SQL = String.Format("WHERE (CDMCU = '{0}') AND (CDITM = {1}) AND (CDCROS = {2}) ", Columns.CDMCU.UnformatColumn(branchPlant), shortItemNumber, outsideCartonID);

            SQL = "GROUP BY CDITM";

            if (Fetch())
            {
                using (RFS_DataManipulator manipulator = new RFS_DataManipulator(DataAccess, "F4620_"))
                {
                    foreach (DataRow row in this.Rows) //make sure to manipulate any not native column
                    {
                        row["TotalBoxQuantity"] = manipulator.ManipulateDataForErp("F4211", "SDSOQS", row["TotalBoxQuantity"]);
                    }
                }

                return true;
            }
            else
            {
                return false;
            }
        }

        #endregion

