        /// <summary>
        /// Determine if the Pallet Record contains multiple different items (aka Mixed)
        /// </summary>
        /// <param name="palletID">Pallet ID (CDCRID)</param>
        /// <returns>True if the Pallet is Mixed, otherwise, False</returns>
        public bool IsMixedPallet(double palletID)
        {
            ResetAll();

            SQL = String.Format("SELECT COUNT(DISTINCT CDITM) AS ItemCount FROM {0} ", GetFullTableName());
