        public bool QuantityRemainingToPack(string BranchPlant, double ShipmentNumber, double ShortItemNumber, string LotNumber)
        {
            ResetAll();

            SQL = "SELECT COALESCE(SUM(SDSOQS), 0) - COALESCE(SUM(CDTQTY), 0) AS RemainingQuantity ";
            SQL = "FROM " + GetFullTableName("F4211") + " ";
            SQL = "LEFT JOIN " + GetFullTableName("F4620") + " ";
            SQL = "ON CDSHPN = SDSHPN AND CDITM = SDITM AND CDLOT = SDLOTN ";

            CDMCU = BranchPlant;
            CDSHPN = ShipmentNumber;
            CDITM = ShortItemNumber;
            CDLOT = LotNumber;

            AppendToWhere("GROUP BY SDSHPN, SDITM, SDLOTN");

            return Fetch();
        }

