            //SQL = "SELECT SUM(CDTQTY) AS CDTQTY, CDMCU, CDSHPN, CDCROS, CDDOCO, CDDCTO, CDLNID, CDLOT, SDKCOO, SDDCTO, SDDOCO, SDLNID, SDSHAN, SDAN8, SDUOM, IMLITM, IMITM, IMAITM, IMDSC1, IMDSC2, IBPRP6, IBSRCE, LMLOCN, LMPZON, LMKZON, LMZONR, LMSTY1, ShipTo.ABALPH AS ShipTo_ABALPH, SoldTo.ABALPH AS SoldTo_ABALPH ";
            SQL = "SELECT SUM(CDTQTY) AS CDTQTY, CDMCU, CDSHPN, CDCROS, CDDOCO, CDDCTO, CDLNID, CDLOT, SDKCOO, SDDCTO, SDDOCO, SDLNID, SDSHAN, SDAN8, SDUOM, IMLITM, IMITM, IMAITM, IMDSC1, IMDSC2, IBPRP6, IBSRCE, ShipTo.ABALPH AS ShipTo_ABALPH, SoldTo.ABALPH AS SoldTo_ABALPH ";
