            //SQL = "ON LMMCU = LPMCU AND LMLOCN = LPLOCN ";
            SQL = "INNER JOIN " + GetFullTableName("F0101") + " AS ShipTo ";
            SQL = "ON ShipTo.ABAN8 = SDSHAN ";
