        #region FindRecordsWithInsufficientQOH

        public bool FindRecordsWithInsufficientQOH(string BranchPlant, double ShipmentNumber, double PalletCrossReferenceNumber, string Location, string[] AllowedOrderStatuses)
        {
            ResetAll();

            SQL = "SELECT CDMCU, CDITM, CDLOT, CDTQTY, COALESCE(LIPQOH, 0) AS LIPQOH ";
            SQL = "FROM (SELECT CDMCU, CDITM, CDLOT, CDDOCO, CDDCTO, CDLNID, CDSHPN, CDCROS, CDURCD, SUM(CDTQTY) AS CDTQTY ";
            SQL = "      FROM " + GetFullTableName() + " ";
            SQL = "      GROUP BY CDMCU, CDITM, CDLOT, CDDOCO, CDDCTO, CDLNID, CDSHPN, CDCROS, CDURCD) F4620_Consolidated ";
            SQL = "LEFT JOIN " + GetFullTableName("F41021") + " ";
            SQL = "ON LIMCU = CDMCU AND LIITM = CDITM AND LILOTN = CDLOT ";
            SQL = "INNER JOIN " + GetFullTableName("F4211") + " ";
            SQL = "ON SDMCU = CDMCU AND SDDOCO = CDDOCO AND SDDCTO = CDDCTO AND SDLNID = CDLNID ";

            CDMCU = BranchPlant;
            CDSHPN = ShipmentNumber;
            CDCROS = PalletCrossReferenceNumber;

            #region WHERE IN for Column SDNXTR

            if (AllowedOrderStatuses.Length != 0 && AllowedOrderStatuses[0] != "" && AllowedOrderStatuses[0] != "*")
            {
                AppendToWhere(string.Format("AND SDNXTR IN ('{0}') AND LTRIM(RTRIM(CDURCD)) = '' AND LILOCN = '" + Location + "' AND CDTQTY > COALESCE(LIPQOH, 0)", string.Join("','", AllowedOrderStatuses)));
            }
            else
            {
                AppendToWhere("AND LTRIM(RTRIM(CDURCD)) = '' AND LILOCN = '" + Location + "' AND CDTQTY > COALESCE(LIPQOH, 0)");
            }

            #endregion

            return Fetch();
        }

        #endregion

